import{_ as o,c as i,o as c,b2 as d}from"./chunks/framework.CUhoHPxN.js";const g=JSON.parse('{"title":"登录日志与登录失败锁定 Implementation Plan","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/plans/2026-05-16-logininfor.md","filePath":"superpowers/plans/2026-05-16-logininfor.md"}'),r={name:"superpowers/plans/2026-05-16-logininfor.md"};function a(t,e,l,n,s,p){return c(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="登录日志与登录失败锁定-implementation-plan" tabindex="-1">登录日志与登录失败锁定 Implementation Plan <a class="header-anchor vp-link" href="#登录日志与登录失败锁定-implementation-plan" aria-label="Permalink to &quot;登录日志与登录失败锁定 Implementation Plan&quot;">​</a></h1><blockquote><p><strong>For agentic workers:</strong> REQUIRED SUB-SKILL: Use superpowers:subagent-driven-development (recommended) or superpowers:executing-plans to implement this plan task-by-task. Steps use checkbox (<code>- [ ]</code>) syntax for tracking.</p></blockquote><p><strong>Goal:</strong> 交付登录日志 CRUD/导出/解锁及登录失败锁定能力；锁定状态仅通过 <code>CacheManager</code> 维护；阈值与开关在 <code>sys_config</code> 内置参数中可配且不可删除。</p><p><strong>Architecture:</strong> Flyway 建 <code>sys_logininfor</code> 表并种子内置参数；<code>LoginLockService</code>（命名以仓库为准）封装 <code>CacheManager.getCache(&quot;qc-login-fail#...&quot;)</code> 的 get/put/evict；<code>AuthController</code>/<code>AuthLoginService</code> 在登录前后调用锁定与写日志；<code>monitor/logininfor</code> 包提供分页与导出；<code>quick-ui</code> 增加 API、路由与列表页。</p><p><strong>Tech Stack:</strong> Spring Boot 3、MyBatis-Plus、Sa-Token、<code>SysConfigService</code>、Spring <code>CacheManager</code>（<code>DynamicTtlRedisCacheManager</code> 或 Caffeine，由现有自动配置决定）、Flyway、Vue 3 + 现有表格/权限体系。</p><p><strong>设计依据：</strong> <code>docs/superpowers/specs/2026-05-16-logininfor-design.md</code></p><hr><h2 id="文件结构-预计创建-修改" tabindex="-1">文件结构（预计创建/修改） <a class="header-anchor vp-link" href="#文件结构-预计创建-修改" aria-label="Permalink to &quot;文件结构（预计创建/修改）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>区域</th><th>路径（示例，实现时可微调包名）</th></tr></thead><tbody><tr><td>迁移</td><td><code>quickboot-web/src/main/resources/db/migration/V17__sys_logininfor.sql</code>（与现有 <code>V15</code>/<code>V16</code> 错开，避免版本冲突）</td></tr><tr><td>实体/Mapper</td><td><code>.../monitor/logininfor/domain</code>、<code>mapper</code>、<code>SysLogininforMapper.xml</code>（若项目用 XML）</td></tr><tr><td>服务</td><td><code>.../monitor/logininfor/service</code>、<code>LoginLockService</code>（或 <code>.../auth/LoginLockService</code> 与登录就近）</td></tr><tr><td>控制器</td><td><code>.../monitor/logininfor/LogininforController</code></td></tr><tr><td>DTO</td><td><code>SysLogininforQueryBo</code>、<code>SysLogininforVo</code> 等</td></tr><tr><td>登录</td><td>修改 <code>AuthController.java</code>、<code>AuthLoginService.java</code></td></tr><tr><td>前端 API</td><td><code>quick-ui/src/api/monitor/logininfor.ts</code></td></tr><tr><td>前端页面</td><td><code>quick-ui/src/views/monitor/logininfor/index.vue</code>（路径与路由约定对齐）</td></tr><tr><td>路由/菜单</td><td>前端路由表 + Flyway <code>sys_menu</code> / <code>sys_role_menu</code></td></tr></tbody></table></div><hr><h3 id="task-1-flyway-—-sys-logininfor-表" tabindex="-1">Task 1: Flyway — <code>sys_logininfor</code> 表 <a class="header-anchor vp-link" href="#task-1-flyway-—-sys-logininfor-表" aria-label="Permalink to &quot;Task 1: Flyway — `sys_logininfor` 表&quot;">​</a></h3><p><strong>Files:</strong></p><ul><li><p>Create: <code>quickboot-web/src/main/resources/db/migration/V{next}__sys_logininfor.sql</code></p></li><li><p>[ ] 编写 DDL：<code>info_id</code> PK、<code>user_id</code>、<code>user_name</code>、<code>ipaddr</code>、<code>login_location</code>、<code>browser</code>、<code>os</code>、<code>status</code>、<code>msg</code>、<code>login_time</code>（索引）、审计字段若项目表惯例需要则对齐 <code>sys_user</code>。</p></li><li><p>[ ] 本地执行 <code>mvn -pl quickboot-web test</code> 或启动验证迁移无报错。</p></li></ul><hr><h3 id="task-2-flyway-—-内置参数-登录锁定" tabindex="-1">Task 2: Flyway — 内置参数（登录锁定） <a class="header-anchor vp-link" href="#task-2-flyway-—-内置参数-登录锁定" aria-label="Permalink to &quot;Task 2: Flyway — 内置参数（登录锁定）&quot;">​</a></h3><p><strong>Files:</strong></p><ul><li><p>Modify: 同上迁移文件或单独 <code>V{next}__sys_config_login_lock.sql</code></p></li><li><p>[ ] <code>INSERT</code> 三条（或合并为一条迁移）：<code>qc.login.fail-lock-enabled</code>、<code>qc.login.max-retry</code>、<code>qc.login.lock-minutes</code>；<code>config_type=&#39;1&#39;</code>；<code>config_value</code> 为约定默认值；<code>config_id</code> 不与现有种子冲突。</p></li><li><p>[ ] 确认 <code>uk_sys_config_key</code> 下键唯一。</p></li></ul><hr><h3 id="task-3-领域模型与-mapper" tabindex="-1">Task 3: 领域模型与 Mapper <a class="header-anchor vp-link" href="#task-3-领域模型与-mapper" aria-label="Permalink to &quot;Task 3: 领域模型与 Mapper&quot;">​</a></h3><p><strong>Files:</strong></p><ul><li><p>Create: Entity、Mapper 接口、<code>SysLogininforMapper.xml</code>（若全注解则省略 XML）</p></li><li><p>[ ] Entity 与表字段一致，MyBatis-Plus <code>@TableName</code> / <code>@TableField</code>。</p></li><li><p>[ ] <code>selectPage</code> 条件：ip、userName、status、<code>login_time</code> between；<code>orderBy</code> 动态。</p></li></ul><hr><h3 id="task-4-loginlockservice-仅-cachemanager" tabindex="-1">Task 4: <code>LoginLockService</code>（仅 CacheManager） <a class="header-anchor vp-link" href="#task-4-loginlockservice-仅-cachemanager" aria-label="Permalink to &quot;Task 4: `LoginLockService`（仅 CacheManager）&quot;">​</a></h3><p><strong>Files:</strong></p><ul><li><p>Create: <code>.../auth/LoginLockService.java</code>（或 monitor 下，以「仅登录使用」为准放 auth）</p></li><li><p>[ ] 注入 <code>CacheManager</code>，常量缓存名如 <code>qc-login-fail#604800</code>（与设计文档一致）。</p></li><li><p>[ ] 方法：<code>isLocked(String userName)</code>、<code>recordFailure(String userName)</code>、<code>clearForUserName(String userName)</code>、<code>onLoginSuccess(String userName)</code>。</p></li><li><p>[ ] 从 <code>SysConfigService</code> 读取三个 config key；<code>enabled=false</code> 时 <code>recordFailure</code> no-op，<code>isLocked</code> false。</p></li><li><p>[ ] 单元测试：使用 <code>DynamicTtlCaffeineCacheManager</code> 或 <code>@SpringBootTest</code> + 测试配置 mock <code>SysConfigService</code> 固定返回值。</p></li></ul><hr><h3 id="task-5-接入登录流程" tabindex="-1">Task 5: 接入登录流程 <a class="header-anchor vp-link" href="#task-5-接入登录流程" aria-label="Permalink to &quot;Task 5: 接入登录流程&quot;">​</a></h3><p><strong>Files:</strong></p><ul><li><p>Modify: <code>AuthController.java</code>、<code>AuthLoginService.java</code></p></li><li><p>[ ] <code>AuthController#login</code>：trim 用户名；在 authenticate 前调用 <code>isLocked</code>；捕获凭据失败时 <code>recordFailure</code> 并写失败日志；成功路径 <code>onLoginSuccess</code> + 写成功日志。</p></li><li><p>[ ] 抽取「写登录日志」到独立小服务，避免 Controller 膨胀；UA/IP/地理解析复用项目已有工具或 Hutool 轻量实现。</p></li><li><p>[ ] 写日志失败 try/catch，打 error，不阻断登录。</p></li></ul><hr><h3 id="task-6-登录日志-controller-service" tabindex="-1">Task 6: 登录日志 Controller + Service <a class="header-anchor vp-link" href="#task-6-登录日志-controller-service" aria-label="Permalink to &quot;Task 6: 登录日志 Controller + Service&quot;">​</a></h3><p><strong>Files:</strong></p><ul><li><p>Create: Controller、Service、QueryBo、Vo、Export DTO（若与 Vo 复用则合并）</p></li><li><p>[ ] <code>GET /monitor/logininfor/list</code> → <code>R&lt;PageInfo&lt;Vo&gt;&gt;</code>。</p></li><li><p>[ ] <code>POST /monitor/logininfor/remove</code> 批量 ID；<code>POST /monitor/logininfor/clean</code>；<code>POST /monitor/logininfor/export</code> Excel（对齐 <code>ExcelUtils</code> 用法）。</p></li><li><p>[ ] <code>GET /monitor/logininfor/unlock/{userName}</code> → 调用 <code>clearForUserName</code> + 明确成功消息。</p></li><li><p>[ ] <code>@SaCheckPermission</code> 与 OpenAPI 注解齐全。</p></li></ul><hr><h3 id="task-7-字典与状态" tabindex="-1">Task 7: 字典与状态 <a class="header-anchor vp-link" href="#task-7-字典与状态" aria-label="Permalink to &quot;Task 7: 字典与状态&quot;">​</a></h3><p><strong>Files:</strong></p><ul><li><p>Modify: <code>V3__sys_dict.sql</code> 或新迁移追加字典类型与数据（若尚无「登录状态」类字典）</p></li><li><p>[ ] 列表 <code>status</code> 与字典 <code>sys_dict</code> 对齐；与写库时赋值约定一致。</p></li></ul><hr><h3 id="task-8-菜单与权限种子" tabindex="-1">Task 8: 菜单与权限种子 <a class="header-anchor vp-link" href="#task-8-菜单与权限种子" aria-label="Permalink to &quot;Task 8: 菜单与权限种子&quot;">​</a></h3><p><strong>Files:</strong></p><ul><li><p>Create: Flyway <code>sys_menu</code>、<code>sys_role_menu</code> 插入（登录日志；父级挂在系统管理或「监控」目录，与产品一致）</p></li><li><p>[ ] <code>perms</code> 与需求四点一致；<code>menu_id</code> 不与 V9/V14 等冲突。</p></li></ul><hr><h3 id="task-9-quick-ui-—-api-与页面" tabindex="-1">Task 9: <code>quick-ui</code> — API 与页面 <a class="header-anchor vp-link" href="#task-9-quick-ui-—-api-与页面" aria-label="Permalink to &quot;Task 9: `quick-ui` — API 与页面&quot;">​</a></h3><p><strong>Files:</strong></p><ul><li><p>Create: <code>src/api/monitor/logininfor.ts</code>、<code>src/views/monitor/logininfor/index.vue</code></p></li><li><p>Modify: 路由模块（与现有 <code>system/config</code> 注册方式一致）</p></li><li><p>[ ] 列表、查询、多选删、清空、导出、解锁按钮及确认框。</p></li><li><p>[ ] 权限指令与后端一致。</p></li><li><p>[ ] <code>pnpm build:prod</code> 通过。</p></li></ul><hr><h3 id="task-10-集成验证" tabindex="-1">Task 10: 集成验证 <a class="header-anchor vp-link" href="#task-10-集成验证" aria-label="Permalink to &quot;Task 10: 集成验证&quot;">​</a></h3><ul><li>[ ] 手工：错误密码 N 次锁定；解锁后可登录；参数页改 <code>max-retry</code> 生效；内置参数删除被后端拒绝。</li><li>[ ] 可选：<code>@SpringBootTest</code> 测 <code>remove</code>/<code>unlock</code> 接口返回结构。</li></ul><hr><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor vp-link" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>业务代码中<strong>不得</strong>出现 <code>RedisTemplate</code>/<code>StringRedisTemplate</code> 操作锁定数据。</li><li>删除/清空接口使用 <strong>POST</strong>（见设计文档）。</li><li>内置参数删除已由 <code>SysConfigServiceImpl.removeBatch</code> 拦截；前端对 <code>configType=== &#39;1&#39;</code> 删除按钮禁用可与参数页现有一致。</li></ul>',51)])])}const h=o(r,[["render",a]]);export{g as __pageData,h as default};
